options.systemMessage:
=## Yêu cầu:
- Trích xuất thông tin từ văn bản và hãy tuân thủ JSON schema tôi cung cấp bên dưới

## Luật
- Không thêm bớt hay chỉnh sửa JSON 
- Giá trị "MaHoSo" thường nằm sau từ "Số: " 
VD: "MaHoSo": "2079965573/TB-TT3"
- Phải đầy đủ nếu như trường nào không có thông tin thì gán `null` 
- Nếu `BenNhan`, `BenGiao`, `TaiSan` không có giá trị nào hoặc giá trị không xác định thì để list rỗng `[]` 


```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Hồ sơ đăng ký bảo đảm",
  "description": "Schema cho việc đăng ký các giao dịch bảo đảm tại Việt Nam",
  "type": "object",
  "definitions": {
    "TaiSan_CoSoKhung": {
      "type": "object",
      "title": "Tài sản có số khung",
      "description": "Phương tiện giao thông cơ giới có số khung như ô tô, mô tô, xe gắn máy, xe máy điện...",
      "properties": {
        "LoaiTaiSan": {
          "const": "TaiSan_CoSoKhung",
          "description": "Loại tài sản - tài sản có số khung"
        },
        "PhuongTien": {
          "type": "string",
          "description": "Tên loại phương tiện (VD: ô tô con, xe mô tô, xe gắn máy, xe tải...)",
          "examples": ["Ô tô con", "Xe mô tô", "Xe gắn máy", "Xe tải"]
        },
        "NhanHieuMauSon": {
          "type": "string", 
          "description": "Nhãn hiệu và màu sơn của phương tiện (VD: Honda màu đỏ, Toyota màu trắng)",
          "examples": ["Honda màu đỏ", "Toyota màu trắng", "Yamaha màu xanh"]
        },
        "SoKhung": {
          "type": "string",
          "description": "Số khung (chassis number) - mã số duy nhất của khung xe",
          "pattern": "^[A-Z0-9]+$",
          "examples": ["JTDBR32E150123456", "VF1BA0D0524123456"]
        },
        "SoMay": {
          "type": "string", 
          "description": "Số máy (engine number) - mã số động cơ của phương tiện",
          "examples": ["G16A123456", "4A91123456"]
        },
        "BienSo": {
          "type": "string",
          "description": "Biển số đăng ký của phương tiện (VD: 43A-12345, 30F1-12345)",
          "pattern": "^[0-9]{2}[A-Z]{1,2}-[0-9]{4,5}$",
          "examples": ["43A-12345", "30F1-54321", "51B-67890"]
        },
        "CanCuThayDoi": {
          "type": "integer",
          "enum": [1, 2],
          "enumDescriptions": [
            "1 - Thế chấp/Cầm cố: Tạo mới giao dịch bảo đảm",
            "2 - Xóa thế chấp/Cầm cố: Hủy bỏ giao dịch bảo đảm hiện có"
          ],
          "description": "Căn cứ thay đổi - lý do thực hiện giao dịch"
        }
      },
      "required": [
        "LoaiTaiSan", 
        "PhuongTien", 
        "NhanHieuMauSon", 
        "SoKhung", 
        "SoMay", 
        "BienSo", 
        "CanCuThayDoi"
      ]
    },

    "TaiSan_KhongCoSoKhung": {
      "type": "object",
      "title": "Tài sản không có số khung",
      "description": "Tàu cá, phương tiện giao thông đường thủy nội địa và các phương tiện không có số khung",
      "properties": {
        "LoaiTaiSan": {
          "const": "TaiSan_KhongCoSoKhung",
          "description": "Loại tài sản - tài sản không có số khung"
        },
        "TenPhuongTienNhanHieu": {
          "type": "string",
          "description": "Tên và nhãn hiệu của phương tiện (VD: Tàu cá Yamaha, Thuyền máy Honda)",
          "examples": ["Tàu cá Yamaha", "Thuyền máy Honda", "Ca nô Suzuki"]
        },
        "TenChuPhuongTien": {
          "type": "string",
          "description": "Họ và tên chủ sở hữu phương tiện theo giấy tờ đăng ký",
          "examples": ["Nguyễn Văn A", "Trần Thị B"]
        },
        "SoDangKyCoQuanCC": {
          "type": "string",
          "description": "Số đăng ký do cơ quan có thẩm quyền cấp (VD: cảng vụ, phòng tài nguyên)",
          "examples": ["TN-001-2024", "CV-123456-2024"]
        },
        "CapPhuongTien": {
          "type": "string",
          "description": "Cấp phương tiện theo quy định (VD: Cấp 1, Cấp 2, Cấp 3)",
          "examples": ["Cấp 1", "Cấp 2", "Cấp 3"]
        },
        "CanCuThayDoi": {
          "type": "integer",
          "enum": [1, 2],
          "enumDescriptions": [
            "1 - Thế chấp/Cầm cố: Tạo mới giao dịch bảo đảm",
            "2 - Xóa thế chấp/Cầm cố: Hủy bỏ giao dịch bảo đảm hiện có"
          ],
          "description": "Căn cứ thay đổi - lý do thực hiện giao dịch"
        }
      },
      "required": [
        "LoaiTaiSan",
        "TenPhuongTienNhanHieu",
        "TenChuPhuongTien", 
        "SoDangKyCoQuanCC",
        "CapPhuongTien",
        "CanCuThayDoi"
      ]
    },

    "TaiSan_QuyenTaiSan": {
      "type": "object",
      "title": "Quyền tài sản",
      "description": "Tài sản bảo đảm là quyền tài sản hoặc một phần quyền tài sản (bản quyền, quyền tác giả, quyền sử dụng đất...)",
      "properties": {
        "LoaiTaiSan": {
          "const": "TaiSan_QuyenTaiSan",
          "description": "Loại tài sản - quyền tài sản"
        },
        "TenQuyen": {
          "type": "string",
          "description": "Tên chính thức của quyền tài sản được nêu trong tài liệu pháp lý, không được tóm tắt hay diễn giải",
          "examples": [
            "Quyền sử dụng đất",
            "Quyền tác giả đối với tác phẩm văn học nghệ thuật", 
            "Quyền sở hữu công nghiệp đối với nhãn hiệu",
            "Quyền khai thác mỏ"
          ]
        },
        "CanCuPhatSinhQuyen": {
          "type": "string",
          "description": "Liệt kê đầy đủ tất cả căn cứ pháp lý phát sinh quyền bao gồm: tên văn bản quy phạm pháp luật, số văn bản, ngày ban hành, ngày có hiệu lực",
          "examples": [
            "Luật Đất đai số 31/2013/QH13 ngày 29/11/2013, có hiệu lực từ 01/07/2014",
            "Luật Sở hữu trí tuệ số 50/2005/QH11 ngày 29/11/2005, có hiệu lực từ 01/07/2006"
          ]
        }
      },
      "required": [
        "LoaiTaiSan",
        "TenQuyen", 
        "CanCuPhatSinhQuyen"
      ]
    },

    "TaiSan_HangHoaLuanChuyen": {
      "type": "object",
      "title": "Hàng hóa luân chuyển và kho hàng",
      "description": "Tài sản bảo đảm là hàng hóa luân chuyển trong quá trình sản xuất kinh doanh hoặc kho hàng (không bao gồm phương tiện giao thông cơ giới đường bộ)",
      "properties": {
        "LoaiTaiSan": {
          "const": "TaiSan_HangHoaLuanChuyen",
          "description": "Loại tài sản - hàng hóa luân chuyển"
        },
        "LoaiKhoHang": {
          "type": "integer",
          "enum": [0, 1],
          "enumDescriptions": [
            "0 - Hàng hóa luân chuyển: Hàng hóa, nguyên vật liệu, thành phẩm thay đổi liên tục",
            "1 - Kho hàng: Cơ sở vật chất cố định để chứa đựng hàng hóa"
          ],
          "description": "Phân loại giữa hàng hóa luân chuyển và kho hàng cố định"
        },
        "GiaTri_TenLoai_HangHoa": {
          "type": "string",
          "description": "Mô tả chi tiết về giá trị, tên gọi và loại hàng hóa (VD: Hàng hóa điện tử trị giá 1 tỷ VND, Nguyên liệu thép các loại)",
          "examples": [
            "Hàng hóa điện tử trị giá 1.000.000.000 VND",
            "Nguyên vật liệu sản xuất giày dép các loại",
            "Thành phẩm may mặc xuất khẩu"
          ]
        },
        "DiaChiKhoHang": {
          "type": "string",
          "description": "Địa chỉ cụ thể của kho hàng hoặc nơi chứa đựng hàng hóa (số nhà, tên đường, phường/xã, quận/huyện, tỉnh/thành phố)",
          "examples": [
            "123 Đường ABC, Phường XYZ, Quận 1, TP.HCM",
            "Km 15, Quốc lộ 1A, Xã DEF, Huyện GHI, Tỉnh JKL"
          ]
        },
        "SoHieuKhoHang": {
          "type": "string", 
          "description": "Số hiệu, mã số hoặc ký hiệu nhận dạng của kho hàng do doanh nghiệp quy định",
          "examples": ["KH-001", "WAREHOUSE-A01", "K1-2024"]
        },
        "CanCuThayDoi": {
          "type": "integer",
          "enum": [1, 2],
          "enumDescriptions": [
            "1 - Thế chấp/Cầm cố: Tạo mới giao dịch bảo đảm",
            "2 - Xóa thế chấp/Cầm cố: Hủy bỏ giao dịch bảo đảm hiện có"
          ],
          "description": "Căn cứ thay đổi - lý do thực hiện giao dịch"
        }
      },
      "required": [
        "LoaiTaiSan",
        "LoaiKhoHang",
        "GiaTri_TenLoai_HangHoa",
        "DiaChiKhoHang", 
        "SoHieuKhoHang",
        "CanCuThayDoi"
      ]
    },

    "CongDanVietNam": {
      "type": "object",
      "title": "Công dân Việt Nam",
      "description": "Thông tin công dân Việt Nam tham gia giao dịch",
      "properties": {
        "HoTen": { 
          "type": "string",
          "description": "Họ và tên đầy đủ theo CCCD/CMND",
          "examples": ["Nguyễn Văn An", "Trần Thị Bình"]
        },
        "CCCD": { 
          "type": "string",
          "description": "Số căn cước công dân hoặc chứng minh nhân dân",
          "pattern": "^[0-9]{9,12}$",
          "examples": ["123456789012", "987654321"]
        },
        "DiaChi": { 
          "type": "string",
          "description": "Địa chỉ thường trú theo CCCD/CMND",
          "examples": ["123 Đường ABC, Phường XYZ, Quận 1, TP.HCM"]
        }
      },
      "required": ["HoTen", "CCCD", "DiaChi"]
    },

    "ToChucTrongNuoc": {
      "type": "object", 
      "title": "Tổ chức trong nước",
      "description": "Doanh nghiệp, tổ chức có đăng ký kinh doanh tại Việt Nam",
      "properties": {
        "TenToChuc": { 
          "type": "string",
          "description": "Tên đầy đủ của tổ chức theo giấy phép kinh doanh",
          "examples": ["Công ty TNHH ABC", "Công ty Cổ phần XYZ"]
        },
        "MaSoThue": { 
          "type": "string",
          "description": "Mã số thuế do cơ quan thuế cấp",
          "pattern": "^[0-9]{10,13}$", 
          "examples": ["0123456789", "0987654321123"]
        },
        "DiaChi": { 
          "type": "string",
          "description": "Địa chỉ trụ sở chính của tổ chức",
          "examples": ["456 Đường DEF, Phường GHI, Quận 3, TP.HCM"]
        }
      },
      "required": ["TenToChuc", "MaSoThue", "DiaChi"]
    },

    "NguoiNuocNgoai": {
      "type": "object",
      "title": "Người nước ngoài", 
      "description": "Cá nhân có quốc t適khác Việt Nam",
      "properties": {
        "HoTen": { 
          "type": "string",
          "description": "Họ và tên đầy đủ theo hộ chiếu",
          "examples": ["John Smith", "Marie Dubois"]
        },
        "SoHoChieu": { 
          "type": "string",
          "description": "Số hộ chiếu (passport number)",
          "examples": ["A12345678", "FR1234567"]
        },
        "QuocGiaCap": { 
          "type": "string",
          "description": "Quốc gia cấp hộ chiếu",
          "examples": ["United States", "France", "Japan"]
        },
        "QuocGia": { 
          "type": "string",
          "description": "Quốc gia cư trú hiện tại",
          "examples": ["Vietnam", "United States", "France"]
        },
        "Tinh": { 
          "type": "string",
          "description": "Tỉnh/thành phố cư trú hiện tại",
          "examples": ["TP.HCM", "Hà Nội", "Đà Nẵng"]
        },
        "DiaChi": { 
          "type": "string",
          "description": "Địa chỉ cư trú chi tiết",
          "examples": ["789 Nguyen Trai St, District 1, HCMC"]
        }
      },
      "required": ["HoTen", "SoHoChieu", "QuocGiaCap", "QuocGia", "Tinh", "DiaChi"]
    },

    "NhaDauTuNuocNgoai": {
      "type": "object",
      "title": "Nhà đầu tư nước ngoài",
      "description": "Tổ chức đầu tư nước ngoài có hoạt động tại Việt Nam",
      "properties": {
        "MaSoThue": { 
          "type": "string",
          "description": "Mã số thuế tại Việt Nam hoặc mã số đăng ký đầu tư",
          "examples": ["8123456789", "DT-001-2024"]
        },
        "Ten": { 
          "type": "string",
          "description": "Tên đầy đủ của tổ chức đầu tư",
          "examples": ["Samsung Electronics Vietnam", "Toyota Motor Vietnam"]
        },
        "QuocGia": { 
          "type": "string",
          "description": "Quốc gia đăng ký thành lập",
          "examples": ["South Korea", "Japan", "Singapore"]
        },
        "Tinh": { 
          "type": "string",
          "description": "Tỉnh/thành phố hoạt động tại Việt Nam",
          "examples": ["TP.HCM", "Hà Nội", "Bắc Ninh"]
        },
        "DiaChi": { 
          "type": "string",
          "description": "Địa chỉ trụ sở tại Việt Nam",
          "examples": ["Tầng 10, Tòa nhà ABC, 123 Đường XYZ, Q.1, TP.HCM"]
        }
      },
      "required": ["MaSoThue", "Ten", "QuocGia", "Tinh", "DiaChi"]
    },

    "ToChucKhac": {
      "type": "object",
      "title": "Tổ chức khác",
      "description": "Các tổ chức không thuộc loại doanh nghiệp hoặc nhà đầu tư nước ngoài",
      "properties": {
        "Ten": { 
          "type": "string",
          "description": "Tên đầy đủ của tổ chức",
          "examples": ["Đại sứ quán Hàn Quốc", "Tổ chức từ thiện ABC"]
        },
        "QuocGia": { 
          "type": "string", 
          "description": "Quốc gia có liên quan đến tổ chức",
          "examples": ["Vietnam", "South Korea", "International"]
        },
        "Tinh": { 
          "type": "string",
          "description": "Tỉnh/thành phố hoạt động",
          "examples": ["Hà Nội", "TP.HCM", "Đà Nẵng"]
        },
        "DiaChi": { 
          "type": "string",
          "description": "Địa chỉ trụ sở hoặc địa điểm hoạt động",
          "examples": ["456 Kim Mã, Ba Đình, Hà Nội"]
        }
      },
      "required": ["Ten", "QuocGia", "Tinh", "DiaChi"]
    },

    "NguoiKhongQuocTich": {
      "type": "object",
      "title": "Người không quốc tịch",
      "description": "Cá nhân không có quốc tịch nhưng cư trú hợp pháp tại Việt Nam",
      "properties": {
        "HoTen": { 
          "type": "string",
          "description": "Họ và tên đầy đủ theo giấy tờ tùy thân",
          "examples": ["Ahmed Hassan", "Maria Santos"]
        },
        "TheCuTru": { 
          "type": "string",
          "description": "Số thẻ cư trú hoặc giấy phép cư trú",
          "examples": ["CR-123456789", "PR-987654321"]
        },
        "QuocGia": { 
          "type": "string",
          "description": "Quốc gia cư trú (thường là Vietnam)",
          "examples": ["Vietnam"]
        },
        "Tinh": { 
          "type": "string",
          "description": "Tỉnh/thành phố cư trú tại Việt Nam", 
          "examples": ["TP.HCM", "Hà Nội", "Cần Thơ"]
        },
        "DiaChi": { 
          "type": "string",
          "description": "Địa chỉ cư trú chi tiết tại Việt Nam",
          "examples": ["321 Đường Cộng Hòa, P.12, Q.Tân Bình, TP.HCM"]
        }
      },
      "required": ["HoTen", "TheCuTru", "QuocGia", "Tinh", "DiaChi"]
    }
  },

  "properties": {
    "MaHoSo": {
      "type": "string",
      "description": "Mã số hồ sơ đăng ký bảo đảm do hệ thống tự động tạo, thường xuất hiện sau cụm từ 'Mã hồ sơ:' hoặc 'Số:'",
      "pattern": "^[A-Z0-9-]+$",
      "examples": ["HS-2024-001234", "BDBB-240615-001"]
    },

    "SoDon": {
      "type": "string", 
      "description": "Số đăng ký giao dịch bảo đảm, là mã số duy nhất của từng đơn đăng ký",
      "examples": ["DK-2024-5678", "001234/ĐKBĐ-2024"]
    },

    "SoDangKyLanDau": {
      "type": "string",
      "description": "Số đăng ký của lần đăng ký đầu tiên (chỉ có khi đây là đơn thay đổi hoặc sửa chữa)",
      "examples": ["DK-2024-1111", "000123/ĐKBĐ-2024"]
    },

    "LoaiDonID": {
      "type": "integer",
      "description": "Mã số định danh loại đơn đăng ký theo quy định của hệ thống",
      "enum": [1, 2, 3, 4, 6, 8, 9, 10],
      "enumDescriptions": [
        "1 - Đăng ký lần đầu: Đăng ký mới một giao dịch bảo đảm",
        "2 - Đăng ký thay đổi: Thay đổi thông tin đăng ký đã có",
        "3 - Sửa chữa sai sót: Chỉnh sửa lỗi trong đăng ký", 
        "4 - Xóa đơn đăng ký: Hủy bỏ đăng ký theo yêu cầu",
        "6 - Xóa đăng ký bởi cơ quan có thẩm quyền: Hủy bỏ theo quyết định hành chính",
        "8 - Cung cấp bản sao: Yêu cầu cấp bản sao hồ sơ",
        "9 - Yêu cầu cấp bản sao kèm thông báo CA: Cấp bản sao có xác thực số",
        "10 - Cung cấp thông tin: Tra cứu thông tin đăng ký"
      ]
    },

    "LoaiDonName": {
      "type": "string",
      "description": "Tên đầy đủ của loại đơn, phải tương ứng với LoaiDonID",
      "examples": ["Đăng ký lần đầu", "Đăng ký thay đổi", "Sửa chữa sai sót"]
    },

    "LoaiDonCode": {
      "type": "string", 
      "description": "Mã viết tắt của loại đơn theo quy định",
      "examples": ["ĐKLD", "ĐKTĐ", "SCSS", "XDD"]
    },

    "LoaiHinhGDID": {
      "type": "integer",
      "description": "Mã số định danh loại hình giao dịch chính",
      "enum": [1, 2, 3],
      "enumDescriptions": [
        "1 - Biện pháp bảo đảm: Giao dịch tạo ra biện pháp bảo đảm (thế chấp, cầm cố...)",
        "2 - Hợp đồng: Giao dịch dựa trên hợp đồng dân sự/thương mại",
        "3 - Thông báo xử lý tài sản bảo đảm: Thông báo về việc xử lý tài sản"
      ]
    },

    "LoaiHinhGDName": {
      "type": "string",
      "description": "Tên đầy đủ loại hình giao dịch, phải khớp với LoaiHinhGDID",
      "examples": ["Biện pháp bảo đảm", "Hợp đồng", "Thông báo xử lý tài sản bảo đảm"]
    },

